// Split diff into chunks under 4K tokens
const diff = $input.first().json.data || '';
const MAX_CHUNK = 12000; // ~4K tokens at ~3 chars/token
const chunks = [];

// Split by file
const files = diff.split('diff --git ');
let currentChunk = '';

for (const file of files) {
  if (!file.trim()) continue;
  if (currentChunk.length + file.length > MAX_CHUNK) {
    if (currentChunk) chunks.push(currentChunk);
    currentChunk = file;
  } else {
    currentChunk += 'diff --git ' + file;
  }
}
if (currentChunk) chunks.push(currentChunk);

return chunks.map((chunk, i) => ({ json: { chunk, chunk_index: i, total_chunks: chunks.length, pr_url: $('GitHub PR Webhook').first().json.body.pull_request.html_url, pr_number: $('GitHub PR Webhook').first().json.body.number, repo: $('GitHub PR Webhook').first().json.body.repository.full_name } }));

// Aggregate all review chunks into one comment
const items = $input.all();
let body = '## AI Code Review\n\n';
body += `> Automated review by n8n + Gemini\n\n`;

for (const item of items) {
  const text = item.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (text.includes('No issues found')) continue;
  body += text + '\n\n---\n\n';
}

if (body.trim().endsWith('---')) {
  body = body.replace(/\n\n---\n\n$/, '');
}

if (!body.includes('##') || body.split('\n').length < 5) {
  body += 'No significant issues found. Looks good.';
}

const repo = items[0]?.json?.repo;
const prNumber = items[0]?.json?.pr_number;

return [{ json: { body, repo, pr_number: prNumber } }];
